1	{
2	  "name": "feature-harbor",
3	  "version": "0.1.0",
4	  "private": true,
5	  "type": "module",
6	  "scripts": {
7	    "start": "node server.ts serve",
8	    "help": "node server.ts --help",
9	    "test": "node --test"
10	  }
11	}
12

1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	
7	const PRODUCT: string = 'FeatureHarbor';
8	const RESOURCE: string = 'ideas';
9	const MAX_TITLE = 120;
10	const MAX_DESCRIPTION = 5000;
11	const MAX_SCENARIO = 1000;
12	const MAX_BODY_BYTES = 1_000_000;
13	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
14	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
15	a{color:#175b9c}
16	label{display:block;font-weight:600;margin-top:1rem}
17	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
18	textarea{resize:vertical}
19	.required{color:#b00020}
20	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
21	#error{color:#b00020;margin-top:.75rem}
22	#success{color:#1a7f37;margin-top:.75rem}
23	.idea{border-top:1px solid #ddd;padding:1rem 0}
24	.idea h3{margin:0 0 .5rem}
25	.pre{white-space:pre-wrap}
26	time{color:#666;font-size:.9rem}
27	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
28	<h2>提交产品意见</h2>
29	<form id="idea-form" novalidate>
30	<label for="f-title">标题 <span class="required">*</span>（必填，最多 120 字）</label>
31	<input id="f-title" name="title" required>
32	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 5000 字）</label>
33	<textarea id="f-desc" name="description" rows="5" required></textarea>
34	<label for="f-scenario">使用场景（可选，最多 1000 字）</label>
35	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
36	<button type="submit">提交意见</button>
37	<p id="error" role="alert" hidden></p>
38	<p id="success" role="status" hidden></p>
39	</form>
40	<h2>意见列表</h2>
41	<p id="empty" hidden>还没有意见记录。</p>
42	<div id="ideas"></div>
43	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
44	</main><script>
45	const form = document.getElementById('idea-form');
46	const titleInput = document.getElementById('f-title');
47	const descInput = document.getElementById('f-desc');
48	const scenarioInput = document.getElementById('f-scenario');
49	const errorBox = document.getElementById('error');
50	const successBox = document.getElementById('success');
51	const emptyNote = document.getElementById('empty');
52	const list = document.getElementById('ideas');
53	const EMPTY_TEXT = '还没有意见记录。';
54	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
55	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
56	let listState = 'loading';
57	function codePoints(text) { return Array.from(text).length; }
58	function showError(message) {
59	  errorBox.textContent = message;
60	  errorBox.hidden = false;
61	  successBox.hidden = true;
62	}
63	function renderIdea(idea) {
64	  const item = document.createElement('article');
65	  item.className = 'idea';
66	  const heading = document.createElement('h3');
67	  heading.textContent = idea.title;
68	  const desc = document.createElement('p');
69	  desc.className = 'pre';
70	  desc.textContent = idea.description;
71	  item.append(heading, desc);
72	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
73	    const scenario = document.createElement('p');
74	    const label = document.createElement('strong');
75	    label.textContent = '使用场景：';
76	    const text = document.createElement('span');
77	    text.className = 'pre';
78	    text.textContent = idea.scenario;
79	    scenario.append(label, text);
80	    item.append(scenario);
81	  }
82	  const time = document.createElement('time');
83	  time.dateTime = idea.createdAt;
84	  const parsed = new Date(idea.createdAt);
85	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
86	  item.append(time);
87	  return item;
88	}
89	let remoteIdeas = [];
90	// 本页已确认保存的意见，最新提交的排在最前
91	const submittedIdeas = [];
92	function renderList() {
93	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
94	  const seen = new Set();
95	  const ordered = [];
96	  for (const idea of submittedIdeas) {
97	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
98	  }
99	  for (const idea of remoteIdeas) {
100	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
101	  }
102	  list.replaceChildren(...ordered.map(renderIdea));
103	  if (listState === 'failed') {
104	    emptyNote.textContent = LOAD_FAILED_TEXT;
105	    emptyNote.hidden = false;
106	  } else if (listState === 'ready') {
107	    emptyNote.textContent = EMPTY_TEXT;
108	    emptyNote.hidden = ordered.length > 0;
109	  } else {
110	    // 首次列表仍在加载，不能把等待误报成没有记录
111	    emptyNote.hidden = true;
112	  }
113	}
114	// 一条有效意见必须是 JSON 对象：id 为非空字符串，
115	// title、description、scenario、createdAt 均为字符串（scenario 允许为空字符串）
116	function isValidIdea(idea) {
117	  if (typeof idea !== 'object' || idea === null || Array.isArray(idea)) return false;
118	  if (typeof idea.id !== 'string' || idea.id.length === 0) return false;
119	  for (const field of ['title', 'description', 'scenario', 'createdAt']) {
120	    if (typeof idea[field] !== 'string') return false;
121	  }
122	  return true;
123	}
124	async function loadIdeas() {
125	  try {
126	    const res = await fetch('/api/ideas');
127	    if (!res.ok) throw new Error('load failed');
128	    const data = await res.json();
129	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都合法；
130	    // 顶层结构异常或任意一条记录异常都属于整次加载失败，
131	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
132	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
133	      throw new Error('invalid ideas response');
134	    }
135	    if (!data.ideas.every(isValidIdea)) throw new Error('invalid idea record');
136	    remoteIdeas = data.ideas;
137	    listState = 'ready';
138	  } catch {
139	    listState = 'failed';
140	  }
141	  renderList();
142	}
143	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
144	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
145	let editVersion = 0;
146	for (const field of [titleInput, descInput, scenarioInput]) {
147	  field.addEventListener('input', () => { editVersion += 1; });
148	}
149	function validate(title, description, scenario) {
150	  const trimmed = title.trim();
151	  if (!trimmed) return '标题不能为空。';
152	  if (codePoints(trimmed) > 120) return '标题最多 120 个字符。';
153	  if (!description.trim()) return '详细说明不能为空。';
154	  if (codePoints(description) > 5000) return '详细说明最多 5000 个字符。';
155	  if (codePoints(scenario) > 1000) return '使用场景最多 1000 个字符。';
156	  return null;
157	}
158	form.addEventListener('submit', async (event) => {
159	  event.preventDefault();
160	  errorBox.hidden = true;
161	  successBox.hidden = true;
162	  const title = titleInput.value;
163	  const description = descInput.value;
164	  const scenario = scenarioInput.value;
165	  const submittedVersion = editVersion;
166	  const problem = validate(title, description, scenario);
167	  if (problem) { showError(problem); return; }
168	  let res;
169	  try {
170	    res = await fetch('/api/ideas', {
171	      method: 'POST',
172	      headers: { 'content-type': 'application/json' },
173	      body: JSON.stringify({ title, description, scenario })
174	    });
175	  } catch {
176	    showError('网络错误，提交未成功，请重试。');
177	    return;
178	  }
179	  let data = null;
180	  try { data = await res.json(); } catch { data = null; }
181	  if (!res.ok) {
182	    showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
183	    return;
184	  }
185	  // 成功状态的响应同样必须结构完整：顶层是含 idea 的 JSON 对象，
186	  // 且 idea 本身通过 isValidIdea 校验（对象、非空 id、各字段均为字符串）。
187	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
188	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
189	  if (typeof data !== 'object' || data === null || Array.isArray(data) || !isValidIdea(data.idea)) {
190	    showError('提交失败，请稍后重试。');
191	    return;
192	  }
193	  // 只有等待期间没有继续编辑（包括改回原文、清空字段也算编辑）才清空表单；
194	  // 否则完整保留此刻的草稿，成功提示与列表仍按本次提交的记录更新
195	  if (editVersion === submittedVersion) form.reset();
196	  successBox.textContent = '提交成功，你的意见已保存。';
197	  successBox.hidden = false;
198	  // 只把已确认保存的意见并入列表，随后统一渲染，避免与首次列表响应相互覆盖
199	  submittedIdeas.unshift(data.idea);
200	  renderList();
201	});
202	loadIdeas();
203	</script></html>`;
204	const args: string[] = process.argv.slice(2);
205	const help: string = `FeatureHarbor - 产品意见与公开路线图
206	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
207	       node server.ts --help
208	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
209	Port 0 selects an available port.
210	`;
211	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
212	  process.stdout.write(help);
213	  process.exit(args.length === 0 ? 2 : 0);
214	}
215	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
216	let host: string = '127.0.0.1';
217	let port: number = 8080;
218	let dataDir: string = 'data';
219	while (args.length) {
220	  const flag = args.shift();
221	  const value = args.shift();
222	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
223	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
224	  }
225	  if (flag === '--host') host = value;
226	  else if (flag === '--port') {
227	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
228	    port = Number(value);
229	  } else dataDir = value;
230	}
231	mkdirSync(dataDir, { recursive: true });
232	const dataFile = join(dataDir, 'ideas.json');
233	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
234	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
235	}
236	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
237	  const body = options.html ? String(value) : JSON.stringify(value);
238	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
239	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
240	  res.end(body);
241	}
242	function codePoints(text: string): number {
243	  return Array.from(text).length;
244	}
245	function readIdeas(): unknown[] {
246	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
247	  if (!Array.isArray(records)) throw new Error('Invalid record list');
248	  return records;
249	}
250	function saveIdeas(records: unknown[]): void {
251	  const tempFile = `${dataFile}.tmp`;
252	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
253	  renameSync(tempFile, dataFile);
254	}
255	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
256	  const chunks: Buffer[] = [];
257	  let size = 0;
258	  for await (const chunk of req as AsyncIterable<Buffer>) {
259	    size += chunk.length;
260	    if (size > MAX_BODY_BYTES) {
261	      respond(res, 400, { error: '请求体过大' });
262	      req.destroy();
263	      return;
264	    }
265	    chunks.push(chunk);
266	  }
267	  let payload: unknown;
268	  try {
269	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
270	  } catch {
271	    respond(res, 400, { error: '请求体不是有效的 JSON' });
272	    return;
273	  }
274	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
275	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
276	    return;
277	  }
278	  const body = payload as Record<string, unknown>;
279	  for (const field of ['title', 'description'] as const) {
280	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
281	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
282	  }
283	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
284	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
285	    return;
286	  }
287	  const title = (body.title as string).trim();
288	  const description = body.description as string;
289	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
290	  if (!title) { respond(res, 400, { error: '标题去掉首尾空白后不能为空' }); return; }
291	  if (codePoints(title) > MAX_TITLE) { respond(res, 400, { error: `标题最多 ${MAX_TITLE} 个字符` }); return; }
292	  if (!description.trim()) { respond(res, 400, { error: '详细说明必须包含非空白内容' }); return; }
293	  if (codePoints(description) > MAX_DESCRIPTION) { respond(res, 400, { error: `详细说明最多 ${MAX_DESCRIPTION} 个字符` }); return; }
294	  if (codePoints(scenario) > MAX_SCENARIO) { respond(res, 400, { error: `使用场景最多 ${MAX_SCENARIO} 个字符` }); return; }
295	  const idea = {
296	    id: randomUUID(),
297	    title,
298	    description,
299	    scenario,
300	    createdAt: new Date().toISOString(),
301	  };
302	  let records: unknown[];
303	  try {
304	    records = readIdeas();
305	  } catch {
306	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
307	    return;
308	  }
309	  records.unshift(idea);
310	  try {
311	    saveIdeas(records);
312	  } catch {
313	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
314	    return;
315	  }
316	  respond(res, 201, { idea });
317	}
318	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
319	  let route: string;
320	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
321	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
322	  if (route === '/api/ideas') {
323	    if (req.method === 'POST') {
324	      handleCreateIdea(req, res).catch(() => {
325	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
326	      });
327	      return;
328	    }
329	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
330	    try {
331	      respond(res, 200, { [RESOURCE]: readIdeas() });
332	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
333	    return;
334	  }
335	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
336	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
337	  respond(res, 200, { status: 'ok', product: PRODUCT });
338	});
339	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
340	server.listen(port, host, (): void => {
341	  const address = server.address();
342	  if (address && typeof address !== 'string') {
343	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
344	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
345	  }
346	});
347	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
348	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
349	}
350

