30	interface El {
31	  tagName: string;
32	  className: string;
33	  hidden: boolean;
34	  value: string;
35	  dateTime: string;
36	  children: El[];
37	  text: string | null;
38	  textContent: string;
39	  listeners: Record<string, Array<(event: unknown) => unknown>>;
40	  append(...nodes: El[]): void;
41	  replaceChildren(...nodes: El[]): void;
42	  addEventListener(type: string, fn: (event: unknown) => unknown): void;
43	  reset(): void;
44	}
45	
46	function makeElement(tag: string): El {
47	  const node = {
48	    tagName: tag.toUpperCase(),
49	    className: '',
50	    hidden: false,
51	    value: '',
52	    dateTime: '',
53	    children: [],
54	    text: null as string | null,
55	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
56	    append(...nodes: El[]): void {
57	      this.children.push(...nodes);
58	    },
59	    replaceChildren(...nodes: El[]): void {
60	      this.children = [...nodes];
61	    },
62	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
63	      (this.listeners[type] ??= []).push(fn);
64	    },
65	    reset(): void {},
66	  };
67	  Object.defineProperty(node, 'textContent', {
68	    get(this: any): string {
69	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
70	    },
71	    set(this: any, value: unknown): void {
72	      this.text = String(value);
73	    },
74	  });
75	  return node as El;
76	}
77	
78	interface Gate {
79	  promise: Promise<unknown>;
80	  resolve: (value: unknown) => void;
81	  reject: (error: Error) => void;
82	}
83	
84	function gate(): Gate {
85	  let resolve!: (value: unknown) => void;
86	  let reject!: (error: Error) => void;
87	  const promise = new Promise<unknown>((res, rej) => {
88	    resolve = res;
89	    reject = rej;
90	  });
91	  return { promise, resolve, reject };
92	}
93	
94	function jsonResponse(status: number, body: unknown): any {
95	  return {
96	    ok: status >= 200 && status < 300,
97	    status,
98	    json: async () => body,
99	  };
100	}
101	
102	function brokenJsonResponse(status = 201): any {
103	  return {
104	    ok: status >= 200 && status < 300,
105	    status,
106	    json: async () => {
107	      throw new SyntaxError('响应体不是有效 JSON');
108	    },
109	  };
110	}
111	
112	const flush = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 0));
113	
114	let ideaSeq = 0;
115	function makeIdea(partial: Record<string, unknown> = {}): Record<string, unknown> {
116	  ideaSeq += 1;
