162	    const documentMock = {
163	      getElementById: (id: string): El => byId.get(id)!,
164	      createElement: (tag: string): El => makeElement(tag),
165	    };
166	    const fetchMock = (url: unknown, init?: { method?: string; body?: unknown }): Promise<unknown> => {
167	      const method = init?.method ?? 'GET';
168	      const pending = gate();
169	      if (method === 'POST') {
170	        this.posts.push(pending);
171	        this.postsIssued += 1;
172	        this.postBodies.push(init?.body);
173	      } else {
174	        this.gets.push(pending);
175	        this.getsIssued += 1;
176	      }
177	      return pending.promise;
178	    };
179	    const context = vm.createContext({ console, document: documentMock, fetch: fetchMock });
180	    vm.runInContext(script, context, { filename: 'inline-page-script.js' });
181	  }
182	
183	  setForm(values: { title?: string; description?: string; scenario?: string }): void {
184	    if (values.title !== undefined) this.els['f-title'].value = values.title;
185	    if (values.description !== undefined) this.els['f-desc'].value = values.description;
186	    if (values.scenario !== undefined) this.els['f-scenario'].value = values.scenario;
187	  }
188	
189	  // 模拟真实用户输入：赋值并触发 input 事件（setForm 不触发事件，只用于布置初始状态）
190	  edit(id: string, value: string): void {
191	    const el = this.els[id];
192	    el.value = value;
193	    for (const fn of el.listeners.input ?? []) fn({ target: el });
194	  }
195	
196	  // 触发表单 submit 监听器，返回监听器（async 函数）的 Promise
197	  submit(): Promise<unknown> {
198	    const handler = this.els['idea-form'].listeners.submit[0];
199	    return handler({ preventDefault(): void {} });
200	  }
201	
202	  articles(): El[] {
203	    return this.els.ideas.children.filter((node) => node.tagName === 'ARTICLE');
204	  }
205	
206	  titles(): string[] {
207	    return this.articles().map((article) => article.children.find((n) => n.tagName === 'H3')!.textContent);
208	  }
209	}
