test('超限请求不影响已有意见的内容与次序；把超限字段缩短到允许范围后可正常提交', async () => {
  // 先保存两条基线意见
  const first = await postIdea({ title: '边界基线一', description: '说明一', scenario: '场景一' });
  assert.equal(first.status, 201);
  const second = await postIdea({ title: '边界基线二', description: '说明二' });
  assert.equal(second.status, 201);
  const baselineIds = (await listIdeas()).map((i) => i.id);
  assert.deepEqual(baselineIds, [second.data.idea.id, first.data.idea.id]);

  // 三个字段分别超限，全部拒绝
  const overTitle = { title: '题'.repeat(121), description: '修正前的说明', scenario: '修正前的场景' };
  const overDesc = { title: '修正后的标题', description: '说'.repeat(5001), scenario: '修正前的场景' };
  const overScenario = { title: '修正后的标题', description: '修正后的说明', scenario: '景'.repeat(1001) };
  for (const body of [overTitle, overDesc, overScenario]) {
    const rejected = await postIdea(body);
    assert.equal(rejected.status, 400);
  }

  // 失败之后，已有意见的内容与顺序都不变，也没有新增记录
  const afterFailures = await listIdeas();
  assert.deepEqual(afterFailures.map((i) => i.id), baselineIds);
  assert.equal(afterFailures[0].title, '边界基线二');
  assert.equal(afterFailures[1].title, '边界基线一');

  // 把超限字段缩短到允许范围（其余内容沿用，含中文、表情与换行），同一条意见应能正常提交
  const fixed = {
    title: '题'.repeat(119) + EMOJI, // 120 码点
    description: '\n' + '说'.repeat(4998) + EMOJI, // 5000 码点，含换行与表情
    scenario: '景'.repeat(999) + EMOJI, // 1000 码点
  };
  assert.equal(cp(fixed.title), MAX_TITLE);
  assert.equal(cp(fixed.description), MAX_DESCRIPTION);
  assert.equal(cp(fixed.scenario), MAX_SCENARIO);
  const accepted = await postIdea(fixed);
  assert.equal(accepted.status, 201, '缩短到上限后之前的错误不能继续阻止保存');
  assert.equal(accepted.data.idea.title, fixed.title);
  assert.equal(accepted.data.idea.description, fixed.description);
  assert.equal(accepted.data.idea.scenario, fixed.scenario);

  // 新意见排在最前，旧意见内容与次序原样保留
  const finalList = await listIdeas();
  assert.deepEqual(finalList.map((i) => i.id), [accepted.data.idea.id, ...baselineIds]);
  assert.deepEqual(finalList.slice(1).map((i) => i.id), baselineIds);
});

