import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';

// 字符上限（按 Unicode 码点：标题 120、详细说明 5000、使用场景 1000）的接口侧回归。
// 只走公开的 POST/GET /api/ideas，回归需要能发现：
// - 把 😀 等表情算成两个字符（UTF-16 长度）或按传输字节（UTF-8）计算长度；
// - 恰好达到上限的内容被错误拒绝；
// - 超限一个码点时被截断保存而不是明确 400 拒绝；
// - 标题首尾空白参与长度判断、详细说明/使用场景的首尾空白与换行未原样保留；
// - 失败请求污染了已有意见的内容或排列次序。

const MAX_TITLE = 120;
const MAX_DESCRIPTION = 5000;
const MAX_SCENARIO = 1000;

let server: StartedServer;

before(async () => {
  server = await startServer();
});

after(async () => {
  await server.stop();
  removeDataDir(server);
});

interface Idea {
  id: string;
  title: string;
  description: string;
  scenario: string;
  createdAt: string;
}

async function postIdea(body: unknown): Promise<{ status: number; data: any }> {
  const res = await fetch(`${server.origin}/api/ideas`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  return { status: res.status, data: await res.json() };
}

async function listIdeas(): Promise<Idea[]> {
  const res = await fetch(`${server.origin}/api/ideas`);
  assert.equal(res.status, 200);
  const data = await res.json();
  assert.ok(Array.isArray(data.ideas));
  return data.ideas as Idea[];
}

const cp = (text: string): number => Array.from(text).length;

// 恰好 1 个码点，但 UTF-8 占 4 个字节、UTF-16 占 2 个码元；
// 任何按字节或码元计长的实现都会在这里与码点规则分歧。
const EMOJI = '😀';
// 多个码点组成的文字：国旗 emoji 由两个区域指示符号码点组成，按码点应累计为 2。
const MULTI = '🇨🇳';
assert.equal(cp(MULTI), 2);

test('表情与多码点文字按码点计长：包含 😀 与国旗序列的内容不受字节/码元计数影响', async () => {
  // 标题：119 个码点（英文/中文混合，单字节或三字节字符都有）+ 😀 = 120 码点。
  // 若按 UTF-16 码元算，😀 占 2，总长度会被当成 121；若按 UTF-8 字节算则远超 120。
  const title = 'a'.repeat(60) + '中'.repeat(59) + EMOJI;
  assert.equal(cp(title), MAX_TITLE);
  // 正文同样混入表情与多码点序列（国旗 = 2 码点、4 UTF-8 字节）
  const description = 'x'.repeat(2490) + '中'.repeat(2500) + EMOJI + MULTI;
  assert.equal(cp(description), MAX_DESCRIPTION);
  const scenario = 's'.repeat(490) + '中'.repeat(508) + EMOJI + MULTI;
  assert.equal(cp(scenario), MAX_SCENARIO);

  const { status, data } = await postIdea({ title, description, scenario });
  assert.equal(status, 201, `码点恰好达上限应接受，实际错误：${JSON.stringify(data.error)}`);
  assert.equal(cp(data.idea.title), MAX_TITLE);
  assert.equal(cp(data.idea.description), MAX_DESCRIPTION);
  assert.equal(cp(data.idea.scenario), MAX_SCENARIO);
});

test('标题恰好 120 个码点（中文）允许提交；首尾空白在判断长度前去除且保存时去掉', async () => {
  // 输入首尾各带空白：按原文（码元或字节）都会更长，按 trim 后的码点恰为 120
  const core = '标'.repeat(MAX_TITLE);
  const raw = '  \t ' + core + ' \n ';
  assert.equal(cp(raw), MAX_TITLE + 7);
  const { status, data } = await postIdea({ title: raw, description: '说明' });
  assert.equal(status, 201, `trim 后恰好 120 码点的标题应接受，实际错误：${JSON.stringify(data.error)}`);
  assert.equal(data.idea.title, core);
});

test('标题内部空白计入长度：119 个字符加一个内部空格到 120 可以，再加一个到 121 拒绝', async () => {
  const exactly = 'a'.repeat(119) + ' ';
  assert.equal(cp(exactly.trim()), 119); // trim 不影响内部空白以外的部分
  const ok = await postIdea({ title: exactly, description: '说明' });
  assert.equal(ok.status, 201);

  // 内部空格前后都有内容，trim 不会缩短它：trim 后恰为 121 码点
  const over = 'a' + ' '.repeat(2) + 'b'.repeat(118);
  assert.equal(cp(over.trim()), 121);
  const rejected = await postIdea({ title: over, description: '说明' });
  assert.equal(rejected.status, 400);
  assert.match(String(rejected.data.error), /标题/);
});

test('详细说明恰好 5000 个码点允许提交；首尾空白与换行计入长度且保存后原样保留', async () => {
  // 首尾空白必须参与长度判断：trim 后只有 4996 个“中”，码点总数为 5000
  const core = '中'.repeat(MAX_DESCRIPTION - 4);
  const description = '  \n' + core + '\n  ';
  assert.equal(cp(description), MAX_DESCRIPTION);
  const { status, data } = await postIdea({ title: '正文边界', description });
  assert.equal(status, 201, `恰好 5000 码点（含首尾空白换行）的正文应接受，实际错误：${JSON.stringify(data.error)}`);
  // 原样保存，不能 trim、不能改行尾
  assert.equal(data.idea.description, description);
  assert.ok(data.idea.description.startsWith('  \n'));
  assert.ok(data.idea.description.endsWith('\n  '));
});

test('带首尾空白的合法上限标题可以提交，而仅被首尾空白推到超限的详细说明必须拒绝', async () => {
  // 标题：trim 后恰好 120，合法
  const title = ' ' + '题'.repeat(MAX_TITLE) + ' ';
  assert.equal(cp(title.trim()), MAX_TITLE);
  const titleRes = await postIdea({ title, description: '合法标题说明' });
  assert.equal(titleRes.status, 201);
  assert.equal(titleRes.data.idea.title, '题'.repeat(MAX_TITLE));

  // 正文：非空白内容只有 4999 码点，但首尾各一个空白把原文推到 5001，
  // 规则按原文（含首尾空白）计长，必须拒绝；不能先 trim 再判断
  const description = ' ' + '说'.repeat(MAX_DESCRIPTION - 1) + ' ';
  assert.equal(cp(description), MAX_DESCRIPTION + 1);
  const descRes = await postIdea({ title: '被空白推超限', description });
  assert.equal(descRes.status, 400);
  assert.match(String(descRes.data.error), /详细说明/);
});

test('使用场景恰好 1000 个码点允许提交并原样保留；省略或显式空字符串仍可提交', async () => {
  const scenario = '场'.repeat(MAX_SCENARIO - 20) + '\n' + ' '.repeat(10) + EMOJI + MULTI + '尾'.repeat(6);
  assert.equal(cp(scenario), MAX_SCENARIO);
  const full = await postIdea({ title: '场景边界', description: '说明', scenario });
  assert.equal(full.status, 201, `恰好 1000 码点的场景应接受，实际错误：${JSON.stringify(full.data.error)}`);
  assert.equal(full.data.idea.scenario, scenario);

  const omitted = await postIdea({ title: '省略场景', description: '说明' });
  assert.equal(omitted.status, 201);
  assert.equal(omitted.data.idea.scenario, '');

  const empty = await postIdea({ title: '空字符串场景', description: '说明', scenario: '' });
  assert.equal(empty.status, 201);
  assert.equal(empty.data.idea.scenario, '');

  // 全空白的场景也是合法字符串（仅按长度约束），应原样保存
  const blank = ' \n\t ';
  const blankRes = await postIdea({ title: '空白场景', description: '说明', scenario: blank });
  assert.equal(blankRes.status, 201);
  assert.equal(blankRes.data.idea.scenario, blank);
});

test('三个字段各超出上限一个码点时均返回 400 与明确错误，且记录不会被截断保存', async (t) => {
  const cases = [
    {
      name: '标题超 1 个码点（中文）',
      body: { title: '题'.repeat(MAX_TITLE + 1), description: '说明' },
      errorMatches: /标题/,
    },
    {
      name: '标题超 1 个码点（😀 只算一个码点）',
      // 119 个中文 + 😀 = 120 合法；120 个中文 + 😀 = 121 超限。
      // 按 UTF-16 码元会把它当 122，按码点则恰为 121。
      body: { title: '题'.repeat(MAX_TITLE) + EMOJI, description: '说明' },
      errorMatches: /标题/,
    },
    {
      name: '详细说明超 1 个码点（含换行与表情）',
      body: { title: '标题', description: 'a'.repeat(4998) + '\n' + EMOJI + MULTI },
      errorMatches: /详细说明/,
    },
    {
      name: '使用场景超 1 个码点（表情）',
      body: { title: '标题', description: '说明', scenario: '景'.repeat(MAX_SCENARIO) + EMOJI },
      errorMatches: /使用场景|scenario/,
    },
  ];
  for (const c of cases) {
    await t.test(c.name, async () => {
      const { status, data } = await postIdea(c.body);
      assert.equal(status, 400);
      assert.equal(typeof data.error, 'string');
      assert.match(data.error, c.errorMatches);

      // 拒绝必须是整条拒绝：列表里不能出现被截断到上限的记录
      const ideas = await listIdeas();
      const leaked = ideas.find(
        (idea) =>
          idea.title === String((c.body as any).title).trim().slice(0, MAX_TITLE) ||
          idea.description === String((c.body as any).description).slice(0, MAX_DESCRIPTION) ||
          (typeof (c.body as any).scenario === 'string' &&
            idea.scenario === String((c.body as any).scenario).slice(0, MAX_SCENARIO)),
      );
      assert.equal(leaked, undefined, '超限内容不得被截断后入库');
    });
  }
});

test('超限请求不影响已有意见的内容与次序；把超限字段缩短到允许范围后可正常提交', async () => {
  // 先保存两条基线意见
  const first = await postIdea({ title: '边界基线一', description: '说明一', scenario: '场景一' });
  assert.equal(first.status, 201);
  const second = await postIdea({ title: '边界基线二', description: '说明二' });
  assert.equal(second.status, 201);
  const baselineIds = (await listIdeas()).map((i) => i.id);
  assert.deepEqual(baselineIds, [second.data.idea.id, first.data.idea.id]);

  // 三个字段分别超限，全部拒绝
  const overTitle = { title: '题'.repeat(121), description: '修正前的说明', scenario: '修正前的场景' };
  const overDesc = { title: '修正后的标题', description: '说'.repeat(5001), scenario: '修正前的场景' };
  const overScenario = { title: '修正后的标题', description: '修正后的说明', scenario: '景'.repeat(1001) };
  for (const body of [overTitle, overDesc, overScenario]) {
    const rejected = await postIdea(body);
    assert.equal(rejected.status, 400);
  }

  // 失败之后，已有意见的内容与顺序都不变，也没有新增记录
  const afterFailures = await listIdeas();
  assert.deepEqual(afterFailures.map((i) => i.id), baselineIds);
  assert.equal(afterFailures[0].title, '边界基线二');
  assert.equal(afterFailures[1].title, '边界基线一');

  // 把超限字段缩短到允许范围（其余内容沿用，含中文、表情与换行），同一条意见应能正常提交
  const fixed = {
    title: '题'.repeat(119) + EMOJI, // 120 码点
    description: '\n' + '说'.repeat(4998) + EMOJI, // 5000 码点，含换行与表情
    scenario: '景'.repeat(999) + EMOJI, // 1000 码点
  };
  assert.equal(cp(fixed.title), MAX_TITLE);
  assert.equal(cp(fixed.description), MAX_DESCRIPTION);
  assert.equal(cp(fixed.scenario), MAX_SCENARIO);
  const accepted = await postIdea(fixed);
  assert.equal(accepted.status, 201, '缩短到上限后之前的错误不能继续阻止保存');
  assert.equal(accepted.data.idea.title, fixed.title);
  assert.equal(accepted.data.idea.description, fixed.description);
  assert.equal(accepted.data.idea.scenario, fixed.scenario);

  // 新意见排在最前，旧意见内容与次序原样保留
  const finalList = await listIdeas();
  assert.deepEqual(finalList.map((i) => i.id), [accepted.data.idea.id, ...baselineIds]);
  assert.deepEqual(finalList.slice(1).map((i) => i.id), baselineIds);
});

