  assert.equal(data.idea.description, description);
  assert.ok(data.idea.description.startsWith('  \n'));
  assert.ok(data.idea.description.endsWith('\n  '));
});

test('带首尾空白的合法上限标题接受，而仅被首尾空白推到 5001 码点的详细说明拒绝', async () => {
