// 标题去掉首尾空白，详细说明与使用场景原样保留。
function savedIdea(form: IdeaForm): Record<string, unknown> {
  return makeIdea({
    id: 'saved-1',
    title: form.title.trim(),
    description: form.description,
    scenario: form.scenario ?? '',
  });
}

